package node

import (
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// Agent instruction files: the folder is the interface. The node
// writes AGENTS.md and CLAUDE.md into the public folder so "make me a
// homepage" works in any coding agent with no explanation from the owner.
// They are never served to visitors (internal/site hides them): the node
// forces them into the folder, so the owner could not move them out to
// keep them private.

// agentFilesMarker identifies generated files; only files carrying it are
// ever overwritten, so an owner's own replacement is left alone.
const agentFilesMarker = "<!-- generated by linknode"

// EnsureAgentFiles writes or refreshes AGENTS.md and CLAUDE.md. address is
// the node's public URL ("" before registration). Call it at startup and
// again after first registration.
func EnsureAgentFiles(publicDir, address, previewAddr string, log *slog.Logger) {
	want := agentFileContent(address, previewAddr)
	for _, name := range []string{"AGENTS.md", "CLAUDE.md"} {
		path := filepath.Join(publicDir, name)
		current, err := os.ReadFile(path)
		switch {
		case err == nil && string(current) == want:
			continue
		case err == nil && !strings.Contains(string(current), agentFilesMarker):
			continue // the owner replaced it; theirs to keep
		case err != nil && !os.IsNotExist(err):
			log.Warn("cannot read agent instruction file", "file", name, "error", err)
			continue
		}
		if err := os.WriteFile(path, []byte(want), 0o644); err != nil {
			log.Warn("cannot write agent instruction file", "file", name, "error", err)
			continue
		}
		log.Info("agent instruction file written", "file", name)
	}
}

// PublicURL returns the node's public address on the service.
func PublicURL(server, nodeID string) string {
	return strings.TrimSuffix(server, "/") + "/" + nodeID + "/"
}

const addressFile = "address"

// SaveAddress remembers the public address the service last gave the
// node, so it can be shown while the service is unreachable. The node
// never derives an address on its own: the service's host is not a
// node address.
func SaveAddress(dataDir, addr string) error {
	if addr == "" || addr == SavedAddress(dataDir) {
		return nil
	}
	return os.WriteFile(filepath.Join(dataDir, addressFile), []byte(addr+"\n"), 0o600)
}

// SavedAddress returns the last address the service gave, or "".
func SavedAddress(dataDir string) string {
	data, err := os.ReadFile(filepath.Join(dataDir, addressFile))
	if err != nil {
		return ""
	}
	addr := strings.TrimSpace(string(data))
	if !strings.HasPrefix(addr, "https://") && !strings.HasPrefix(addr, "http://") {
		return ""
	}
	return addr
}

// agentRules are extra numbered rules after the core ones: features the
// node has add their own (see addAgentRule). Each gets the node ID.
var agentRules []func(nodeID string) string

// addAgentRule appends a rule; rule returns its text without the number,
// continuation lines indented by three spaces. Call it from init.
func addAgentRule(rule func(nodeID string) string) { agentRules = append(agentRules, rule) }

var addressIDRE = regexp.MustCompile(`^https?://([0-9a-hjkmnp-z]{8})\.|/([0-9a-hjkmnp-z]{8})/?$`)

// nodeIDFromAddress picks the node ID out of a public address, or "".
func nodeIDFromAddress(address string) string {
	m := addressIDRE.FindStringSubmatch(address)
	if m == nil {
		return ""
	}
	if m[1] != "" {
		return m[1]
	}
	return m[2]
}

func agentFileContent(address, previewAddr string) string {
	nodeID := nodeIDFromAddress(address)
	if nodeID == "" {
		nodeID = "YOUR-NODE-ID"
	}
	if address == "" {
		address = "not registered yet — it appears here once the node first reaches the server"
	}
	return fmt.Sprintf(`%s; version 1. The owner may replace this file with
their own instructions — a file without this marker line is never
overwritten by the node. This file is not served to visitors. -->

# This folder is a live website

You are in the public folder of a Link Node. Every file here is served as a
static website directly from this computer, peer-to-peer, to anyone who
opens the address. There is no build step and no deployment: saving a file
here IS publishing it (once the owner has flipped the publish switch).

- Public address: %s
- Local preview while the node runs: %s

## Rules

1. `+"`index.html`"+` is the homepage. Relative links, stylesheets and
   images work like on any static site.
2. Static files only: nothing here is ever executed on a server. In the
   visitor's browser your pages' scripts DO run — the published site lives
   on its own origin (its own subdomain), which allows inline scripts,
   the site's own files and any https: source — so galleries, lightboxes
   and embeds are fine.
3. Files and folders whose names start with a dot (.git, .env, …) are
   never served, and neither are these two instruction files. Everything
   else is public: do not put secrets, API keys or private data anywhere
   in this folder.
4. `+"`offline.html`"+` is special: Link.us shows it when this computer is
   off or unreachable. Only this one file is mirrored, so keep it under
   64 KB and self-contained: inline styles; images as data: URIs (they
   count toward the cap) or from https: URLs (they don't). Scripts,
   external stylesheets, fonts and forms never work on it. Give links a
   target: target="_blank" (new tab) or target="_top" (same tab);
   mailto: and tel: links work as they are.
5. Cookies are not private to this site. Every node address shares one
   parent domain with every other node, so other node sites can set
   cookies this site receives, and count as "same-site" to browsers. Never
   build logins, sessions or anything security-related on cookies or
   SameSite rules here, never set a cookie with a Domain attribute, and
   treat any cookie you read as possibly planted by someone else.
   (localStorage is fine: it stays with this site's own address.)
6. If this folder holds the example site ("Alex's Place"), it is a
   sample: before the owner publishes, replace its name, stories, photos,
   items for sale and contact details (alex@example.com) with the
   owner's own, or remove those pages. Ask the owner what they want to
   share.
%s
## For the owner

- `+"`linknode publish on|off`"+` puts the folder online or takes it off.
- `+"`linknode public`"+` lists exactly what visitors can fetch.
- `+"`linknode log`"+` shows recent visits.
`, agentFilesMarker, address, LocalURL(previewAddr), extraRules(nodeID))
}

// extraRules numbers the features' rules after the six core ones. A
// feature returns "" to leave its rule out.
func extraRules(nodeID string) string {
	var b strings.Builder
	n := 7
	for _, rule := range agentRules {
		text := strings.TrimRight(rule(nodeID), "\n")
		if text == "" {
			continue
		}
		fmt.Fprintf(&b, "%d. %s\n", n, text)
		n++
	}
	return b.String()
}
